"""Original schema, used only by the explicit migration command and fixtures."""
BASE_SQL = "\n        CREATE TABLE IF NOT EXISTS users (\n          id INTEGER PRIMARY KEY, username TEXT UNIQUE COLLATE NOCASE,\n          salt TEXT NOT NULL, password TEXT NOT NULL, reminder TEXT DEFAULT '18:00',\n          reminder_on INTEGER DEFAULT 0, timezone TEXT DEFAULT 'Europe/Vienna');\n        CREATE TABLE IF NOT EXISTS exams (\n          id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id),\n          title TEXT NOT NULL, subject TEXT NOT NULL, exam_date TEXT NOT NULL,\n          difficulty INTEGER NOT NULL, grade INTEGER, completed INTEGER DEFAULT 0);\n        CREATE TABLE IF NOT EXISTS sessions (\n          id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id),\n          exam_id INTEGER REFERENCES exams(id), subject TEXT NOT NULL,\n          date TEXT NOT NULL, seconds REAL NOT NULL, resources TEXT NOT NULL,\n          location TEXT NOT NULL, interruptions INTEGER DEFAULT 0,\n          public INTEGER DEFAULT 0);\n        CREATE TABLE IF NOT EXISTS active (\n          user_id INTEGER PRIMARY KEY REFERENCES users(id), exam_id INTEGER REFERENCES exams(id),\n          subject TEXT NOT NULL, started REAL NOT NULL, paused REAL,\n          paused_total REAL DEFAULT 0, interruptions INTEGER DEFAULT 0, date TEXT NOT NULL);\n        CREATE TABLE IF NOT EXISTS friendships (\n          sender INTEGER REFERENCES users(id), receiver INTEGER REFERENCES users(id),\n          accepted INTEGER DEFAULT 0, PRIMARY KEY(sender, receiver));\n        CREATE TABLE IF NOT EXISTS posts (\n          id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id),\n          text TEXT NOT NULL, subject TEXT NOT NULL, title TEXT NOT NULL,\n          seconds REAL NOT NULL, grade INTEGER, created TEXT NOT NULL);\n        CREATE TABLE IF NOT EXISTS comments (\n          id INTEGER PRIMARY KEY, post_id INTEGER REFERENCES posts(id),\n          user_id INTEGER REFERENCES users(id), text TEXT NOT NULL, created TEXT NOT NULL);\n        "
GROUP_SQL = '\n    CREATE TABLE IF NOT EXISTS study_groups (\n      id INTEGER PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL,\n      owner_id INTEGER NOT NULL REFERENCES users(id));\n    CREATE TABLE IF NOT EXISTS members (\n      group_id INTEGER REFERENCES study_groups(id), user_id INTEGER REFERENCES users(id),\n      PRIMARY KEY(group_id,user_id));\n    CREATE TABLE IF NOT EXISTS group_exams (\n      id INTEGER PRIMARY KEY, group_id INTEGER REFERENCES study_groups(id),\n      creator_id INTEGER REFERENCES users(id), title TEXT NOT NULL, subject TEXT NOT NULL,\n      exam_date TEXT NOT NULL, updated TEXT NOT NULL);\n    CREATE TABLE IF NOT EXISTS exam_files (\n      id INTEGER PRIMARY KEY, exam_id INTEGER REFERENCES exams(id),\n      group_exam_id INTEGER REFERENCES group_exams(id), uploader_id INTEGER REFERENCES users(id),\n      filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL,\n      content BLOB NOT NULL, created TEXT NOT NULL,\n      CHECK ((exam_id IS NULL) != (group_exam_id IS NULL)));\n    CREATE TABLE IF NOT EXISTS notices (\n      id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), text TEXT NOT NULL,\n      created TEXT NOT NULL);\n    CREATE TABLE IF NOT EXISTS auth_sessions (\n      token_hash TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id),\n      csrf TEXT NOT NULL, expires REAL NOT NULL);\n    CREATE TABLE IF NOT EXISTS auth_attempts (bucket TEXT NOT NULL, created REAL NOT NULL);\n    CREATE INDEX IF NOT EXISTS auth_attempts_bucket ON auth_attempts(bucket,created);\n    '

def initialize(db):
    for statement in (BASE_SQL + GROUP_SQL).split(";"):
        if statement.strip():
            db.execute(statement)
    if "group_exam_id" not in {r[1] for r in db.execute("PRAGMA table_info(exams)")}:
        db.execute("ALTER TABLE exams ADD COLUMN group_exam_id INTEGER REFERENCES group_exams(id)")
    db.execute("CREATE UNIQUE INDEX IF NOT EXISTS exam_adoption ON exams(user_id,group_exam_id) WHERE group_exam_id IS NOT NULL")
